phase1.code:
fn main() {
    // Integer types
    let a: i8 = 127;          // -128 to 127
    let b: u8 = 255;          // 0 to 255
    let c: i32 = 100_000;     // Most common
    let d: i64 = 9_223_372_036_854_775_807;
    let e: isize = 10;        // Platform-dependent

    // Floating point types
    let f: f32 = 3.14;        // 32-bit float
    let g: f64 = 3.14159;     // 64-bit float (default)

    // Boolean type
    let is_ready: bool = true;
    let is_done: bool = false;

    // Character type (4 bytes, Unicode)
    let letter: char = 'A';
    let smiley: char = '😊';
    let chinese: char = '中';

    println!("i8: {}", a);
    println!("u8: {}", b);
    println!("i32: {}", c);
    println!("i64: {}", d);
    println!("isize: {}", e);
    println!("f32: {}", f);
    println!("f64: {}", g);
    println!("bool: {}", is_ready);
    println!("char: {}", letter);
    println!("Emoji: {}", smiley);
    println!("Chinese: {}", chinese);
}

